  "python": "def pilot_policy(trace):
    import json
    current_action, current_label = trace[-1]
    action_name = current_action.name
    args = json.loads(current_action.arguments)
    if action_name == 'coordinator/send':
        target = args.get('target')
        if target == 'candidate':
            allowed = {'INTERNAL_SCORE'}
            if not current_label.subset.issubset(allowed):
                raise PolicyViolation('Data sent to candidate includes disallowed categories')
        elif target == 'jobs':
            allowed = {'PII', 'INTERNAL_SCORE'}
            if not current_label.subset.issubset(allowed):
                raise PolicyViolation('Data sent to jobs includes disallowed categories')
    return None"
